package vn.tuan.service;
import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.client.RestClient;import org.springframework.http.*;import org.springframework.util.LinkedMultiValueMap;import org.springframework.core.io.ByteArrayResource;import java.nio.file.*;import java.util.*;import java.security.*;
@Service public class MediaService {
 @Value("${app.media.provider:local}")String provider;@Value("${app.cloudinary.cloud-name:}")String cloud;@Value("${app.cloudinary.api-key:}")String key;@Value("${app.cloudinary.api-secret:}")String secret;
 public String upload(MultipartFile f,boolean video){if(f==null || f.isEmpty())return null;OrderRules.require(f.getSize()<=10*1024*1024,"Tệp tối đa 10 MB");try{byte[] bytes=f.getBytes();String ext;if(bytes.length>8 && bytes[0]==(byte)0x89 && bytes[1]==80 && bytes[2]==78 && bytes[3]==71)ext="png";else if(bytes.length>3 && bytes[0]==(byte)0xff && bytes[1]==(byte)0xd8 && bytes[2]==(byte)0xff)ext="jpg";else if(bytes.length>12 && new String(bytes,0,4,java.nio.charset.StandardCharsets.US_ASCII).equals("RIFF") && new String(bytes,8,4,java.nio.charset.StandardCharsets.US_ASCII).equals("WEBP"))ext="webp";else if(video && bytes.length>12 && new String(bytes,4,4,java.nio.charset.StandardCharsets.US_ASCII).equals("ftyp"))ext="mp4";else throw new IllegalArgumentException("Chỉ nhận ảnh PNG/JPEG/WebP hoặc video MP4 cho đánh giá");String name=UUID.randomUUID()+"."+ext;
 if("cloudinary".equals(provider)){OrderRules.require(!cloud.isBlank() && !key.isBlank() && !secret.isBlank(),"Chưa cấu hình Cloudinary");String timestamp=Long.toString(java.time.Instant.now().getEpochSecond());String sign=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(("timestamp="+timestamp+secret).getBytes(java.nio.charset.StandardCharsets.UTF_8)));var body=new LinkedMultiValueMap<String,Object>();body.add("timestamp",timestamp);body.add("api_key",key);body.add("signature",sign);body.add("file",new ByteArrayResource(bytes){@Override public String getFilename(){return name;}});org.springframework.http.client.SimpleClientHttpRequestFactory factory=new org.springframework.http.client.SimpleClientHttpRequestFactory();factory.setConnectTimeout(5000);factory.setReadTimeout(20000);Map<?,?> result=RestClient.builder().requestFactory(factory).build().post().uri("https://api.cloudinary.com/v1_1/"+cloud+"/"+(ext.equals("mp4")?"video":"image")+"/upload").contentType(MediaType.MULTIPART_FORM_DATA).body(body).retrieve().body(Map.class);if(result==null || result.get("secure_url")==null)throw new IllegalArgumentException("Cloudinary chưa trả về URL");return result.get("secure_url").toString();}
 Path dir=Paths.get("uploads/media");Files.createDirectories(dir);Files.write(dir.resolve(name),bytes,StandardOpenOption.CREATE_NEW);return "/uploads/media/"+name;
 }catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalArgumentException("Không tải được tệp. Kiểm tra cấu hình dịch vụ và thử lại.");}}
}
